CREATE OR REPLACE FUNCTION public.protect_paused_work_item() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.repair_item_id IS DISTINCT FROM OLD.repair_item_id OR NEW.work_order_id IS DISTINCT FROM OLD.work_order_id THEN RAISE EXCEPTION 'work_item_identity_is_immutable'; END IF; IF (OLD.quotation_paused OR OLD.is_archived) AND current_user NOT IN ('postgres','service_role','supabase_admin') THEN RAISE EXCEPTION 'quotation_change_awaiting_approval'; END IF; IF current_user NOT IN ('postgres','service_role','supabase_admin') AND (NEW.quotation_paused IS DISTINCT FROM OLD.quotation_paused OR NEW.is_archived IS DISTINCT FROM OLD.is_archived) THEN RAISE EXCEPTION 'not_authorized'; END IF; END IF; IF TG_OP='INSERT' AND current_user NOT IN ('postgres','service_role','supabase_admin') THEN RAISE EXCEPTION 'use_quotation_revision'; END IF; IF TG_OP='DELETE' AND current_user NOT IN ('postgres','service_role','supabase_admin') AND EXISTS(SELECT 1 FROM public.inspection_work_orders WHERE id=OLD.work_order_id) THEN RAISE EXCEPTION 'use_quotation_revision'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.guard_work_item_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w public.inspection_work_orders%ROWTYPE; BEGIN SELECT * INTO w FROM public.inspection_work_orders WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.work_order_id ELSE NEW.work_order_id END FOR UPDATE; IF NOT FOUND AND TG_OP='DELETE' THEN RETURN OLD; END IF; IF current_setting('role',true)='authenticated' THEN IF public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'executive') THEN PERFORM public.authorize_quotation_revision(w.inspection_id); ELSIF w.contractor_id IS DISTINCT FROM public.current_contractor_id() OR w.status NOT IN ('in_progress','rejected') THEN RAISE EXCEPTION 'not_authorized'; END IF; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.guard_revision_order_delete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF current_setting('role',true)='authenticated' AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'admin_only'; END IF; RETURN OLD; END $$;
CREATE TRIGGER guard_revision_order_delete BEFORE DELETE ON public.inspection_work_orders FOR EACH ROW EXECUTE FUNCTION public.guard_revision_order_delete();
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.assign_work_order(uuid,uuid)'::regprocedure) INTO def; def:=replace(def,'SELECT * INTO v_insp FROM public.inspections WHERE id = p_inspection_id FOR UPDATE;','PERFORM public.authorize_quotation_revision(p_inspection_id); SELECT * INTO v_insp FROM public.inspections WHERE id = p_inspection_id FOR UPDATE;'); EXECUTE def;
SELECT pg_get_functiondef('public.reassign_work_order(uuid,uuid)'::regprocedure) INTO def; def:=replace(def,'IF v_wo.status = ''approved''','PERFORM public.authorize_quotation_revision(v_wo.inspection_id); IF v_wo.status = ''approved'''); EXECUTE def;
SELECT pg_get_functiondef('public.review_work_order(uuid,boolean,text)'::regprocedure) INTO def; def:=replace(def,'IF v_wo.status <> ''in_review''','PERFORM public.authorize_quotation_revision(v_wo.inspection_id); IF v_wo.status <> ''in_review'''); EXECUTE def;
END $$;